<script lang="ts">import {goto} from '$app/navigation';import {auth} from '$lib/api';import {session} from '$lib/stores/session';import TopNav from '$lib/components/TopNav.svelte';let email=$state(''),password=$state(''),error=$state(''),loading=$state(false);async function submit(){if(!email||!password){error='Enter your email and password.';return}loading=true;error='';try{const {user}=await auth.login(email,password);session.set(user);await goto('/dashboard')}catch(e){error=e instanceof Error?e.message:'Unable to log in.'}finally{loading=false}}</script>
<svelte:head><title>Login · RegenFeed</title></svelte:head><TopNav/><main class="auth-page"><section class="auth-story"><a class="auth-brand" href="/">REGEN<span>FEED</span></a><div><p class="eyebrow light">ORGANIC VALUE · IN EVERY CYCLE</p><h1>Welcome back<br/>to the <em>loop.</em></h1><p>Manage orders, move organic materials and settle instantly in sats.</p></div><div class="auth-proof"><i class="fa-solid fa-leaf"></i><span>Built for the people growing Kisumu's circular economy.</span></div></section><section class="auth-form-wrap"><form class="auth-card" onsubmit={(e)=>{e.preventDefault();submit()}}><div><p class="eyebrow">SECURE ACCOUNT ACCESS</p><h2>Log in</h2><p class="muted">Enter the details linked to your RegenFeed account.</p></div>{#if error}<p class="error" role="alert">{error}</p>{/if}<label>Email address<div class="input-shell"><i class="fa-regular fa-envelope"></i><input bind:value={email} type="email" autocomplete="email" placeholder="you@example.com" required /></div></label><label>Password<div class="input-shell"><i class="fa-solid fa-lock"></i><input bind:value={password} type="password" autocomplete="current-password" placeholder="Your password" required /></div></label><button class="btn primary auth-submit" disabled={loading}>{loading?'Logging in…':'Log in'} <i class="fa-solid fa-arrow-right"></i></button><p class="auth-switch">New to RegenFeed? <a href="/auth/register">Create an account</a></p></form></section></main>
